using System;

namespace StdbModule;

public static partial class FrenchQuotes
{
    public static class RenéChar
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "L'homme fuit l'asphyxie.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "L'homme dont l'appétit hors de l'imagination se calfeutre sans finir de s'approvisionner, se délivrera par les mains, rivières soudainement grossies.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "L'homme qui s'épointe dans la prémonition, qui déboise son silence intérieur et le répartit en théâtres, ce second c'est le faiseur de pain.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Aux uns la prison et la mort. Aux autres la transhumance du Verbe.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Sur les arêtes de notre amertume, l'aurore de la conscience s'avance et dépose son limon.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "J'ai lié les unes aux autres mes convictions et agrandi ta Présence. J'ai octroyé un cours nouveau à mes jours en les adossant à cette force spacieuse.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "La menace s'est polie. La plage qui chaque hiver s'encombrait de régressives légendes, de sibylles aux bras lourds d'orties, se prépare aux êtres à secourir.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "J'ai, captif, épousé le ralenti du lierre à l'assaut de la pierre de l'éternité.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "O nuit, je n'ai rapporté de ta félicité que l'apparence parfumée d'ellipses d'oiseaux insaisissables ! Rien n'imposait le mouvement que ta main de pollen qui fondait sur mon front aux moulinets d'une lampe d'anémone.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Je m'appuie un moment sur la pelle du déluge et chantourne sa langue. Mes sueurs d'agneau noir provoquent le sarcasme. Ma nausée se grossit de soudains consentements dont je n'arrive pas à maintenir le cours. Anneau tard venu, enclavé dans la chevalerie pythienne saturée de feu et de vieillesse, quel compagnon engagerais-je ? Je prends place inaperçu sur le tirant de l'étrave jusqu'à la date fleurie où rougeoiera ma cendre.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Ce frère brutal mais dont la parole était sûre, patient au sacrifice, diamant et sanglier, ingénieux et secourable, se tenait au centre de tous les malentendus tel un arbre de résine dans le froid inalliable. Au bestiaire de mensonges qui le tourmentait de ses gobelins et de ses trombes il opposait son dos perdu dans le temps. Il venait à vous par des sentiers invisibles, favorisait l'audace écarlate, ne vous contrariait pas, savait sourire. Comme l'abeille quitte le verger pour le fruit déjà noir, les femmes soutenaient sans le trahir le paradoxe de ce visage qui n'avait pas des traits d'otage.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "J'ai essayé de vous décrire ce compère indélébile que nous sommes quelques-uns à avoir fréquenté. Nous dormirons dans l'espérance, nous dormirons en son absence, puisque la raison ne soupçonne pas que ce qu'elle nomme, à la légère, absence, occupe le fourneau dans l'unité.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Sorgue qui t'avances derrière un rideau de papillons qui pétillent, ta faucille de doyen loyal à la main, la crémaillère du supplice en collier à ton cou, pour accomplir ta journée d'homme, quand pourrais-je m'éveiller et me sentir heureux au rythme modelé de ton seigle irréprochable ?", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "La création et la risée se dissocient. L'air-roi s'annonce. Sorgue, tes épaules comme un livre ouvert propagent leur lecture. Tu as été, enfant, le fiancé de cette fleur au chemin tracé dans le rocher qui s'évadait par un frelon... Courbé, tu observes aujourd'hui l'agonie du persécuteur qui arracha à l'aimant de la terre la cruauté d'innombrables fourmis pour la jeter en millions de meurtriers contre les tiens et ton espoir. Écrase donc encore une fois cet œuf cancéreux qui résiste...", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "L'enfant que, la nuit venue, l'hiver descendait avec précaution de la charrette de la lune, une fois à l'intérieur de la maison balsamique, plongeait d'un seul trait ses yeux dans le foyer de fonte rouge. Derrière l'étroit vitrail incendié l'espace ardent le tenait entièrement captif. Le buste incliné vers la chaleur, ses jeunes mains scellées à l'envolée de feuilles sèches du bien-être, l'enfant épelait la rêverie du ciel glacé.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Tellement j'ai faim, je dors sous la canicule des preuves.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Afin que le mal demeure sans relève, j'ai étouffé ses engagements. J'ai effacé son chiffre de la gaucherie de mon étrave. J'ai répliqué aux coups.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "On tuait de si près que le monde s'est voulu meilleur. Brumaire de mon âme jamais escaladé, qui fait feu dans la bergerie déserte ? Ce n'est plus la volonté elliptique de la scrupuleuse solitude. Aile double des cris d'un million de crimes se levant soudain dans des yeux jadis négligents, montrez-nous vos desseins et cette large abdication du remords !", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "L'été et notre vie étions d'un seul tenant\nLa campagne mangeait la couleur de ta jupe odorante.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "L'imagination consiste à expulser de la réalité plusieurs personnes incomplètes pour, mettant à contribution les puissances magiques et subversives du désir, obtenir leur retour sous la forme d'une présence entièrement satisfaisante. C'est alors l'inextinguible réel incréé.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Ce dont le poète souffre le plus dans ses rapports avec le monde, c'est du manque de justice interne. La vitre-cloaque de Caliban derrière laquelle les yeux tout-puissants et sensibles d'Ariel s'irritent.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Le poète transforme indifféremment la défaite en victoire, la victoire en défaite, empereur prénatal seulement soucieux du recueil de l'azur.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Il convient que la poésie soit inséparable du prévisible, mais non encore formulé.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Fureur et mystère tour à tour le séduisirent et le consumèrent. Puis vint l'année qui acheva son agonie de saxifrage.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Compagnons pathétiques qui murmurez à peine, allez la lampe éteinte et rendez les bijoux. Un mystère nouveau chante dans vos os. Développez votre étrangeté légitime.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Par un travail physique intense on se maintient au niveau du froid extérieur et, ce faisant, on supprime le risque d'être annexé par lui ; ainsi, à l'heure du retour au réel non suscité par notre désir, lorsque le temps est venu de confier à son destin le vaisseau du poème, nous nous trouvons dans une situation analogue. Les roues — ces gravats — de notre moulin pétrifié s'élancent, raclant des eaux basses et difficiles. Notre effort réapprend des sueurs proportionnelles. Et nous allons, lutteurs à terre mais jamais mourants, au milieu de témoins qui nous exaspèrent et de vertus indifférentes.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Refuser la goutte d'imagination qui manque au néant, c'est se vouer à la patience de rendre à l'éternel le mal qu'il nous fait.\nO urne de laurier dans un ventre d'aspic !", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Mourir, ce n'est jamais que contraindre sa conscience, au moment même où elle s'abolit, à prendre congé de quelques quartiers physiques actifs ou somnolents d'un corps qui nous fut passablement étranger puisque sa connaissance ne nous vint qu'au travers d'expédients mesquins et sporadiques. Gros bourg sans grâce au brouhaha duquel s'employaient des habitants modérés... Et au-dessus de cet atroce hermétisme s'élançait une colonne d'ombre à face voûtée, endolorie et à demi aveugle, de loin en loin — ô bonheur — scalpée par la foudre.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Terre mouvante, horrible, exquise et condition humaine hétérogène se saisissent et se qualifient mutuellement. La poésie se tire de la somme exaltée de leur moire.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Le poète est l'homme de la stabilité unilatérale.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Un être qu'on ignore est un être infini, susceptible, en intervenant, de changer notre angoisse et notre fardeau en aurore artérielle.\nEntre innocence et connaissance, amour et néant, le poète étend sa santé chaque jour.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Le poète en traduisant l'intention en acte inspiré, en convertissant un cycle de fatigues en fret de résurrection, fait entrer l'oasis du froid par tous les pores de la vitre de l'accablement et crée le prisme, hydre de l'effort, du merveilleux, de la rigueur et du déluge, ayant tes lèvres pour sagesse et mon sang pour retable.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Le logement du poète est des plus vagues ; le gouffre d'un feu triste soumissionne sa table de bois blanc.\nLa vitalité du poète n'est pas une vitalité de l'au-delà mais un point diamanté actuel de présences transcendantes et d'orages pèlerins.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Traverser avec le poème la pastorale des déserts, le don de soi aux furies, le feu moisissant des larmes. Courir sur ses talons, le prier, l'injurier. L'identifier comme étant l'expression de son génie ou encore l'ovaire écrasé de son appauvrissement. Par une nuit, faire irruption à sa suite, enfin, dans les noces de la grenade cosmique.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Inexpugnable sous sa tente de cyprès, le poète, pour se convaincre et se guider, ne doit pas craindre de se servir de toutes les clefs accourues dans sa main. Cependant il ne doit pas confondre une animation de frontières avec un horizon révolutionnaire.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Ne souriez pas. Écartez le scepticisme et la résignation, et préparez votre âme mortelle en vue d'affronter intra-muros des démons glacés analogues aux génies microbiens.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Un homme sans défauts est comme une montagne sans crevasses. Il ne m'intéresse pas.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "L'acte est vierge, même répété.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Les souris de l'enclume. Cette image m'aurait paru charmante autrefois. Elle suggère un essaim d'étincelles décimé en son éclair. (L'enclume est froide, le fer pas rouge, l'imagination dévastée.)", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "On ne se bat bien que pour les causes qu'on modèle soi-même et avec lesquelles on se brûle en s'identifiant.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Agir en primitif et prévoir en stratège.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Tu ne peux pas te relire mais tu peux signer.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "L'éternité n'est guère plus longue que la vie.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Nous sommes pareils à ces poissons retenus vifs dans la glace des lacs de montagne. La matière et la nature semblent les protéger cependant qu'elles limitent à peine la chance du pêcheur.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "La contre-terreur c'est ce vallon que peu à peu le brouillard comble, c'est le fugace bruissement des feuilles comme un essaim de fusées engourdies, c'est cette pesanteur bien répartie, c'est cette circulation ouatée d'animaux et d'insectes tirant mille traits sur l'écorce tendre de la nuit, c'est cette graine de luzerne sur la fossette d'un visage caressé, c'est cet incendie de la lune qui ne sera jamais un incendie, c'est un lendemain minuscule dont les intentions nous sont inconnues, c'est un buste aux couleurs vives qui s'est plié en souriant, c'est l'ombre, à quelques pas, d'un bref compagnon accroupi qui pense que le cuir de sa ceinture va céder... Qu'importent alors l'heure et le lieu où le diable nous a fixé rendez-vous !", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Tiens vis-à-vis des autres ce que tu t'es promis à toi seul. Là est ton contrat.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Résistance n'est qu'espérance. Telle la lune d'Hypnos, pleine cette nuit de tous ses quartiers, demain vision sur le passage des poèmes.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Les rares moments de liberté sont ceux durant lesquels l'inconscient se fait conscient et le conscient néant (ou verger fou).", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Le cendres du froid sont dans le feu qui chante le refus.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Le peuple des prés m'enchante. Sa beauté frêle et dépourvue de venin, je ne me lasse pas de me la réciter. Le campagnol, la taupe, sombres enfants perdus dans la chimère de l'herbe, l'orvet, fils du verre, le grillon, moutonnier comme pas un, la sauterelle qui claque et compte son linge, le papillon qui simule l'ivresse et agace les fleurs de ses hoquets silencieux, les fourmis assagies par la grande étendue verte, et immédiatement au-dessus les météores hirondelles...\nPrairie, vous êtes le boîtier du jour.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "J'envie cet enfant qui se penche sur l'écriture du soleil, puis s'enfuit vers l'école, balayant de son coquelicot pensums et récompenses.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "L'homme est capable de faire ce qu'il est incapable d'imaginer. Sa tête sillonne la galaxie de l'absurde.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Considère sans être affecté que ce que le mal pique le plus volontiers ce sont les cibles non averties dont il a pu s'approcher à loisir. Ce que tu as appris des hommes — leurs revirements incohérents, leurs humeurs inguérissables, leur goût du fracas, leur subjectivité d'arlequin — doit t'inciter, une fois l'action consommée, à ne pas t'attarder trop sur les lieux de vos rapports.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Ta dictée n'a ni achèvement ni fin. Souchetée seulement d'absences, de volets arrachés, de pures inactions.\nJuxtapose à la fatalité la résistance à la fatalité. Tu connaîtras d'étranges hauteurs.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Je vois enfin la mer dans sa triple harmonie, la mer qui tranche de son croissant la dynastie des douleurs absurdes, la grande volière sauvage, la mer crédule comme un liseron.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Quand je dis : 'j'ai levé la loi, j'ai franchi la morale, j'ai maillé le cœur', ce n'est pas pour me donner raison devant ce pèse-néant dont la rumeur étend sa palme au delà de ma persuasion. Mais rien de ce qui m'a vu vivre et agir jusqu'ici n'est témoin alentour. Mon épaule peut bien sommeiller, ma jeunesse accourir. C'est de cela seul qu'il faut tirer richesse immédiate et opérante.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "J'ai marché sur le miroir d'une rivière pleine d'anneaux de couleuvre et de danses de papillons.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "La connaissance eut tôt fait de grandir entre nous. 'Ceci n'est plus', avais-je coutume de dire. 'Ceci n'est pas', corrigeait-il. 'Pas' et 'plus' étaient disjoints. Il m'offrait, à la gueule d'un serpent qui souriait, mon impossible que je pénétrais sans souffrir. D'où venait cet Ami ? Sans doute, du moins sombre, du moins ouvrier des soleils. Son énergie que je jugeais grande éclatait en fougères patientes, humidité pour mon espoir. Ce dernier, en vérité, n'était qu'une neige de l'existence, l'affinité du renouveau. Un butin s'amoncelait, dessinant le littoral cruel que j'aurais un jour à parcourir. Le cœur de mon Ami m'entrait dans le cœur comme un trident, cœur souverain égaillé dans des conquêtes bientôt réduites en cendres, pour marquer combien la tentation se déprime chez qui s'établit, se rend. Nos confidences ne construiraient pas d'église ; le mutisme reconduisait tous nos pouvoirs.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Je vis qu'il n'y aurait jamais de femme pour moi dans MA ville. La frénésie des cascades, symboliquement, acquitterait mon bon vouloir.\nJ'ai remonté ainsi l'âge de la solitude jusqu'à la demeure suivante de L'HOMME VIOLET. Mais il ne disposait là que du morose état civil de ses prisons, de son expérience muette de persécuté, et nous n'avions, nous, que son signalement d'évadé.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Ma convoitise est infinie. Rien ne m'obsède que la vie.\nÉtincelle nomade qui meurt dans son incendie.\nAime riveraine. Dépense ta vérité. L'herbe qui cache l'or de ton amour ne connaîtra jamais le gel.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "La parole soulève plus de terre que le fossoyeur ne le peut.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "L'essentiel est sans cesse menacé par l'insignifiant.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Vivre, c'est s'obstiner à achever un souvenir.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Le réel quelquefois désaltère l'espérance. C'est pourquoi contre toute attente, l'espérance survit.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "C'est le peu qui est réellement tout. Le peu occupe une place immense. Il nous accepte indisponibles.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Désir, voyageur à l'unique bagage et aux multiples trains.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "À chaque effondrement des preuves le poète répond par une salve d'avenir.", Author = "René Char" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/René_Char", Text = "Mais qu'est-ce qu'un révolté, Monsieur ? Quand un homme est broyé et qu'il se tait, c'est un individu normal. S'il proteste et réclame son droit, c'est un révolutionnaire !", Author = "René Char" },
        };
    }
}